        for candidate in range(1, int(line_count) + 2):
            if candidate * (candidate - 1) / 2 == line_count:
                return candidate
        return None

    n_A = principal_quantum_number(N_lines_A)
    n_B = principal_quantum_number(N_lines_B)
    if n_A is None or n_B is None or n_A < 2 or n_B < 2:
        return {"cannot": "The spectral-line counts must correspond to valid excited principal quantum numbers."}

    wavelength_A_at_unit_Z = step_66(n=n_A, lower_level=n_A - 1, Z=1)["wavelength"]
    wavelength_B_at_unit_Z = step_66(n=n_B, lower_level=1, Z=1)["wavelength"]

    def energy_difference(z_A):
        wavelength_A_longest = step_66(n=n_A, lower_level=n_A - 1, Z=z_A)["wavelength"]
        z_B = math.sqrt(wavelength_B_at_unit_Z / wavelength_A_longest)
        wavelength_A_shortest = step_66(n=n_A, lower_level=1, Z=z_A)["wavelength"]
        wavelength_B_shortest = step_66(n=n_B, lower_level=1, Z=z_B)["wavelength"]
        energy_A = step_58(wavelength=wavelength_A_shortest)["photon_energy"]
        energy_B = step_58(wavelength=wavelength_B_shortest)["photon_energy"]
        return abs(energy_A - energy_B)

    unit_difference = energy_difference(1)
    if unit_difference == 0:
        return {"cannot": "The given transitions do not determine the atomic numbers from the stated nonzero energy difference."}
    upper_bound = max(2, 2 * math.sqrt(delta_E_shortest / unit_difference))
    z_A_continuous = solve_for(
        lambda z_A: energy_difference(z_A) - delta_E_shortest,
        0,
        upper_bound
    )

    z_A = round(z_A_continuous)
    wavelength_A_longest = step_66(n=n_A, lower_level=n_A - 1, Z=z_A)["wavelength"]
    z_B = round(math.sqrt(wavelength_B_at_unit_Z / wavelength_A_longest))

    reference_ground_energy = step_60(n=1, Z=1)["electron_energy"]
    scale = E_H_ground / reference_ground_energy
    ground_energy_A = step_60(n=1, Z=z_A)["electron_energy"] * scale
    ground_energy_B = step_60(n=1, Z=z_B)["electron_energy"] * scale
